sys_script_include.script:
var XalientAccessItemSync = Class.create();
XalientAccessItemSync.prototype = Object.extendsObject(x_xal_idconnect.XalientUtilitiesCore, {
	initialize: function () {
	},

	inboundSync: function () {
		//Grabs all access items in SailPoint and upserts them against the access item table
		const access_token = this.getToken();
		const access_item_filter = gs.getProperty('x_xal_idconnect.inbound_sync_filter') || '*';

		const rm_req_body = {
			"indices": [
				"roles",
				"accessprofiles",
				"entitlements"
			],
			"query": {
				"query": access_item_filter
			},
			"sort": [
				"id"
			]
		};

		const access_items = this.getPaginatedSearchResults(rm_req_body);

		for (const item of access_items) {
			const gr_access_item = new GlideRecord('x_xal_idconnect_sailpoint_access_item_staging');
			gr_access_item.initialize();

			//Common attributes
			gr_access_item.u_name = item?.name;
			gr_access_item.u_description = item?.description;
			gr_access_item.u_requestable = item.requestable;
			gr_access_item.u_sailpoint_id = item.id;
			gr_access_item.u_active = true;
			gr_access_item.u_sailpoint_object_type = item.type;

			//Access Item Ownership
			gr_access_item.u_owner = this.getSnUserAttribute('email',item.owner?.email,'sys_id');

			//Access Profile and Entitlement-specific attributes
			gr_access_item.u_sailpoint_source_name = item.source?.name;
			gr_access_item.u_sailpoint_source_id = item.source?.id;
			gr_access_item.u_sailpoint_entitlement_value = item?.value;
			gr_access_item.u_sailpoint_so_titlement_type = item?.sourceSchemaObjectType;
			gr_access_item.u_privileged = item?.privileged;

			gr_access_item.insert();
		}
	},

	outboundReconciliation: function () {
		//Checks and sees if access items on the ServiceNow side still exist on the SailPoint tenant and inactivates them if not
	},
	type: 'XalientAccessItemSync'
});
